      "acceptanceCriteria": "Each Books and Toys L2 has 2-3 L3 children. NLIV > 0.40.",
      "passes": false
    },
    {
      "id": 13,
      "title": "Expand L3: Sporting Goods + Tools subcategories (2-3 each)",
      "acceptanceCriteria": "Each Sporting Goods and Tools L2 has 2-3 L3 children. NLIV > 0.40.",
      "passes": false
    },
    {
      "id": 14,
      "title": "Expand L3: Pet Products + Cosmetics subcategories (2-3 each)",
      "acceptanceCriteria": "Each Pet Products and Cosmetics L2 has 2-3 L3 children. NLIV > 0.40.",
      "passes": false
    },
    {
      "id": 15,
      "title": "Expand L3: Automotive + Outdoor subcategories (2-3 each)",
      "acceptanceCriteria": "Each Automotive and Outdoor L2 has 2-3 L3 children. NLIV > 0.40.",
      "passes": false
    },
    {
      "id": 16,
      "title": "Refine: Fix weak edges (NLIV < 0.3)",
      "acceptanceCriteria": "Zero weak edges. NLIV mean > 0.50.",
      "passes": false
    },
    {
      "id": 17,
      "title": "Refine: MECE audit and balance",
      "acceptanceCriteria": "CSC > 0.35. Zero chains. Branching CV < 0.8.",
      "passes": false
    },
    {
      "id": 18,
      "title": "Refine: Final optimization",
      "acceptanceCriteria": "Composite > 0.60. NLIV > 0.50. CSC > 0.35. >=200 nodes.",
      "passes": false
    }
  ]
